class Solution {
public:
    int findMinimumTime(vector<int>& strength, int k) {
        int n = strength.size();
        vector<int> memo(1 << n, -1);

        auto dfs = [&](auto& self, int mask) -> int {
            if (mask == (1 << n) - 1) return 0;
            if (memo[mask] != -1) return memo[mask];

            int cnt = __builtin_popcount(mask);
            int x = 1 + cnt * k;
            int ans = INT_MAX;
            for (int j = 0; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    int timeTaken = (strength[j] + x - 1) / x;
                    ans = min(ans, timeTaken + self(self, mask | (1 << j)));
                }
            }
            return memo[mask] = ans;
        };

        return dfs(dfs, 0);
    }
};

class Solution {
    public int findMinimumTime(List<Integer> strength, int k) {
        int n = strength.size();
        Integer[] memo = new Integer[1 << n];
        return dfs(0, strength, k, n, memo);
    }

    private int dfs(int mask, List<Integer> strength, int k, int n, Integer[] memo) {
        if (mask == (1 << n) - 1) return 0;
        if (memo[mask] != null) return memo[mask];

        int cnt = Integer.bitCount(mask);
        int x = 1 + cnt * k;
        int ans = Integer.MAX_VALUE;
        for (int j = 0; j < n; ++j) {
            if ((mask & (1 << j)) == 0) {
                int timeTaken = (strength.get(j) + x - 1) / x;
                ans = Math.min(ans, timeTaken + dfs(mask | (1 << j), strength, k, n, memo));
            }
        }
        return memo[mask] = ans;
    }
}

var findMinimumTime = function(strength, k) {
    const n = strength.length;
    const memo = new Int32Array(1 << n).fill(-1);

    const dfs = (mask) => {
        if (mask === (1 << n) - 1) return 0;
        if (memo[mask] !== -1) return memo[mask];

        let cnt = 0;
        for (let b = 0; b < n; b++) if (mask & (1 << b)) cnt++;
        const x = 1 + cnt * k;
        let ans = Infinity;
        for (let j = 0; j < n; j++) {
            if (!(mask & (1 << j))) {
                const timeTaken = Math.floor((strength[j] + x - 1) / x);
                ans = Math.min(ans, timeTaken + dfs(mask | (1 << j)));
            }
        }
        return memo[mask] = ans;
    };

    return dfs(0);
};
